    candidate = "\n".join(candidate_lines).strip()
    return candidate


class LadderParser(_BaseParser):
    """
    Parser implementing the extraction contract described in the module
    docstring, using verifiers' Parser interface as its base (if available).
    """

    def parse_answer(self, completion: Union[str, List[Any]]) -> Optional[str]:
        scope_text = _extract_scope_text(completion)

        # RUNG 1: ```python fence
        candidate = _find_last_python_fence(scope_text)
        if candidate is not None:
            # Selection already happened; EMPTY RULE applies here.
            if candidate.strip() == "":
                return ""
            return candidate

        # No rungs hit
        return None


def build_parser() -> LadderParser:
    """Build and return the parser implementing the extraction contract."""
    return LadderParser()
