"""
Extraction module implementing a strict, ordered "ladder" contract for
pulling a final answer out of a language-model completion, using the
`verifiers` library's Parser interface.

Contract summary
-----------------
1. SCOPE: only the last message's content matters. A plain string
   completion is its own scope. List-typed content is the concatenation
   (with a single joining space) of all `"type": "text"` parts, stripped.
2. THINK-STRIP: none — <think> sections are ordinary text.
3. THE LADDER (first HIT wins):
     RUNG 1: <answer> ... </answer> tag (last opening tag that has a
              closing tag somewhere after it; content up to the FIRST
              closing tag after that opening tag).
     RUNG 2: last properly-closed ```python code fence.
     RUNG 3: last non-empty line of the scope text.
4. EMPTY RULE: if a rung's selected candidate strips to "", that rung
   MISSES and the ladder proceeds to the next rung (no backtracking to
   earlier occurrences within the same rung).
5. If every rung misses, return None.
"""

import re
from typing import Optional, Any

try:
    # Prefer the real base class from the `verifiers` library if available.
    import verifiers as vf
    _BaseParser = vf.Parser
except Exception:  # pragma: no cover - fallback if verifiers isn't importable
    class _BaseParser:
        def __init__(self, *args, **kwargs):
            pass


_ANSWER_OPEN_RE = re.compile(r'<answer>')
_ANSWER_CLOSE_RE = re.compile(r'</answer>')

_PYTHON_FENCE_RE = re.compile(
    r'^```python[^\n]*\r?\n(.*?)\r?\n^```[ \t]*$',
    re.DOTALL | re.MULTILINE,
)


def _get_content(message: Any) -> Any:
    """Extract the raw `content` field from a message dict or object."""
    if isinstance(message, dict):
        return message.get("content", "")
    return getattr(message, "content", "")


def _content_to_text(content: Any) -> str:
    """Turn a message's content (string or list-of-parts) into scope text."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        texts = []
        for part in content:
            if isinstance(part, dict) and part.get("type") == "text":
                texts.append(part.get("text", ""))
        return " ".join(texts).strip()
    return ""


def _get_scope(completion: Any) -> str:
    """Determine the scope text according to the SCOPE rule."""
    if isinstance(completion, str):
        return completion
    if isinstance(completion, list) and len(completion) > 0:
        last_message = completion[-1]
        content = _get_content(last_message)
        return _content_to_text(content)
    return ""


def _rung1_answer_tag(text: str) -> Optional[str]:
    """RUNG 1: <answer>...</answer> extraction.

    Returns None if there is no qualifying <answer> occurrence (structural
    miss). Returns the stripped candidate string otherwise (which may be
    empty, triggering the EMPTY RULE fallthrough at the caller level).
    """
    starts = [m.start() for m in _ANSWER_OPEN_RE.finditer(text)]
    if not starts:
        return None
    closes = [m.start() for m in _ANSWER_CLOSE_RE.finditer(text)]
    if not closes:
        return None

    for s in reversed(starts):
        close_pos = next((c for c in closes if c > s), None)
        if close_pos is not None:
            content_start = s + len('<answer>')
            candidate = text[content_start:close_pos]
            return candidate.strip()

    return None


def _rung2_python_fence(text: str) -> Optional[str]:
    """RUNG 2: last properly closed ```python fence."""
    matches = _PYTHON_FENCE_RE.findall(text)
    if not matches:
        return None
    return matches[-1].strip()


def _rung3_last_line(text: str) -> Optional[str]:
    """RUNG 3: last non-empty line of the scope text."""
    lines = text.splitlines()
    for line in reversed(lines):
        if line.strip() != "":
            return line.strip()
    return None


def _apply_ladder(text: str) -> Optional[str]:
    for rung in (_rung1_answer_tag, _rung2_python_fence, _rung3_last_line):
        candidate = rung(text)
        if candidate is not None and candidate != "":
            return candidate
    return None


class LadderAnswerParser(_BaseParser):
    """Parser implementing the exact extraction contract described above."""

    def parse_answer(self, completion: Any) -> Optional[str]:
        scope_text = _get_scope(completion)
        return _apply_ladder(scope_text)


def build_parser() -> LadderAnswerParser:
    """Build and return the parser implementing the extraction contract."""
    return LadderAnswerParser()
