"""
extraction_parser.py

A module implementing a strict, deterministic "ladder" style answer
extraction contract on top of the `verifiers` library's Parser interface.

The contract (summarized):
  1. SCOPE: only the last message's content matters. Plain strings are
     their own scope. List-typed content: join text-typed parts with a
     single space, then strip.
  2. THINK-STRIP: none -- <think> blocks are ordinary text.
  3. THE LADDER (first HIT wins):
       RUNG 1: <answer>...</answer> tag -- last <answer> that has a
               </answer> after it; content between that open tag and the
               first following close tag, stripped.
       RUNG 2: last ```python ... ``` fence (closed), stripped.
       RUNG 3: last non-empty line, stripped.
  4. EMPTY RULE: if a rung's *selected* candidate strips to "", that rung
     MISSES and we fall through to the next rung (no re-selection within
     the same rung).
  5. If every rung misses, return None.
"""

import re

try:
    from verifiers import Parser as _BaseParser
except Exception:  # pragma: no cover - fallback if verifiers isn't installed
    class _BaseParser:
        pass


_ANSWER_OPEN = "<answer>"
_ANSWER_CLOSE = "</answer>"

_OPEN_FENCE_RE = re.compile(r"(?m)^```python[^\n]*$")
_CLOSE_FENCE_RE = re.compile(r"(?m)^```[ \t]*$")


def _extract_scope_from_content(content):
    """Given a message's `content` (string or list of parts), return the
    scope text per the SCOPE rule."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        texts = []
        for part in content:
            if isinstance(part, dict) and part.get("type") == "text":
                texts.append(part.get("text", ""))
        return " ".join(texts).strip()
    # Unknown content type: treat as empty scope.
    return ""


def _get_scope(completion):
    """Determine the scope text from a completion."""
    if isinstance(completion, str):
        return completion

    if isinstance(completion, list):
        if not completion:
            return ""
        last = completion[-1]

        if isinstance(last, dict):
            content = last.get("content")
        else:
            content = getattr(last, "content", None)

        return _extract_scope_from_content(content)

    # Fallback: unknown completion type.
    return ""


def _rung1_answer_tag(text):
    """RUNG 1: last <answer> occurrence with a </answer> after it."""
    open_positions = [m.start() for m in re.finditer(re.escape(_ANSWER_OPEN), text)]
    for pos in reversed(open_positions):
        content_start = pos + len(_ANSWER_OPEN)
        close_pos = text.find(_ANSWER_CLOSE, content_start)
        if close_pos != -1:
            candidate = text[content_start:close_pos].strip()
            return candidate  # selection made; no fallback to earlier occurrence
    return None  # no occurrence had a closing tag -> MISS


def _rung2_python_fence(text):
    """RUNG 2: last ```python fence that is properly closed by ```."""
    opens = list(_OPEN_FENCE_RE.finditer(text))
    for m in reversed(opens):
        # position right after the opening fence's line
        after_open = m.end()
        # skip the newline right after the opening line, if present
        search_start = after_open
        if search_start < len(text) and text[search_start] == "\n":
            search_start += 1

        close_match = _CLOSE_FENCE_RE.search(text, search_start)
        if close_match is not None:
            candidate = text[search_start:close_match.start()].strip()
            return candidate  # selection made; no fallback to earlier occurrence
    return None  # no properly closed fence -> MISS


def _rung3_last_nonempty_line(text):
    """RUNG 3: the last line containing any non-whitespace character."""
    lines = text.split("\n")
    for line in reversed(lines):
        if line.strip() != "":
            return line.strip()
    return None


def _extract_answer(scope_text):
    """Run the ladder on the scope text, applying the EMPTY RULE."""
    # RUNG 1
    candidate = _rung1_answer_tag(scope_text)
    if candidate is not None and candidate != "":
        return candidate

    # RUNG 2
    candidate = _rung2_python_fence(scope_text)
    if candidate is not None and candidate != "":
        return candidate

    # RUNG 3
    candidate = _rung3_last_nonempty_line(scope_text)
    if candidate is not None and candidate != "":
        return candidate

    return None


class LadderParser(_BaseParser):
    """A Parser implementing the exact extraction contract described in
    the module docstring."""

    def parse_answer(self, completion):
        scope_text = _get_scope(completion)
        return _extract_answer(scope_text)


def build_parser():
    """Build and return a parser implementing the extraction contract."""
    return LadderParser()
